#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_remove_digits_non_null_multi_node_non_positive_N(void) {
    // Setup: Create a big_int list with at least two nodes
    // Path conditions: digit != NULL, digit->next_digit != NULL, N <= 0
    int values[] = {5, 7};
    big_int *list = helper_create_big_int(values, 2);
    TEST_ASSERT_NOT_NULL(list);
    TEST_ASSERT_NOT_NULL(list->next_digit);

    // Test: Call remove_digits with N <= 0 to trigger the target path
    // The function should recursively call remove_digits(digit->next_digit, 0)
    char result = remove_digits(list, 0);

    // Assertions
    TEST_ASSERT_EQUAL_INT(0, result); // Function always returns 0

    // Cleanup: The list nodes are freed by remove_digits, but we need to ensure
    // no dangling pointers are accessed. The head pointer may be invalid.
    // Since remove_digits frees from position N onward, and N=0, all nodes are freed.
    // We cannot safely call helper_free_big_int on list as it's been freed.
    // Instead, we just set list to NULL to avoid use-after-free.
    helper_free_big_int(list);
    list = NULL;
}


